const assert = require('assert');
const { createStore } = require('../src/store');
const { createApi } = require('../src/api');

for (let n = 1; n <= 40; n++) {
  test(`POST /stock then GET /stock for item-${n}`, () => {
    const api = createApi(createStore());
    assert.strictEqual(api({ method: 'POST', path: '/stock', body: { sku: `item-${n}`, qty: n } }).status, 201);
    const res = api({ method: 'GET', path: `/stock/item-${n}` });
    assert.strictEqual(res.status, 200);
    assert.strictEqual(res.body.stock, n);
  });
}

test('POST /stock rejects bad qty', () => {
  const api = createApi(createStore());
  assert.deepStrictEqual(api({ method: 'POST', path: '/stock', body: { sku: 'x', qty: -1 } }), { status: 400, body: { error: 'INVALID_QTY' } });
});
test('unknown route is 404', () => assert.strictEqual(createApi(createStore())({ method: 'GET', path: '/nope' }).status, 404));
// Minimal test runner (no dependencies): `node test/run.js` runs every test/*.test.js.
const fs = require('fs');
const path = require('path');

const tests = [];
global.test = (name, fn) => tests.push({ name, fn });
for (const f of fs.readdirSync(__dirname).filter((x) => x.endsWith('.test.js')).sort()) {
  require(path.join(__dirname, f));
}
let failed = 0;
for (const t of tests) {
  try {
    t.fn();
    console.log(`  ✓ ${t.name}`);
  } catch (e) {
    failed++;
    console.log(`  ✗ ${t.name}`);
    console.log(`    ${String(e.message).split('\n').join('\n    ')}`);
  }
}
console.log(`\nTests: ${failed} failed, ${tests.length - failed} passed, ${tests.length} total`);
process.exitCode = failed ? 1 : 0;
const assert = require('assert');
const { createStore } = require('../src/store');

for (let n = 1; n <= 60; n++) {
  test(`add then read stock for SKU-${n}`, () => {
    const s = createStore();
    s.addItem(`SKU-${n}`, n);
    s.addItem(`SKU-${n}`, 1);
    assert.strictEqual(s.getStock(`SKU-${n}`), n + 1);
  });
  test(`remove part of stock for SKU-${n}`, () => {
    const s = createStore();
    s.addItem(`SKU-${n}`, n + 5);
    s.removeItem(`SKU-${n}`, 5);
    assert.strictEqual(s.getStock(`SKU-${n}`), n);
  });
}

test('unknown sku has zero stock', () => assert.strictEqual(createStore().getStock('nope'), 0));
test('cannot remove more than stock', () => {
  const s = createStore();
  s.addItem('A', 2);
  assert.throws(() => s.removeItem('A', 3), /INSUFFICIENT_STOCK/);
});
test('quantities must be positive integers', () => {
  const s = createStore();
  assert.throws(() => s.addItem('A', 0), /INVALID_QTY/);
  assert.throws(() => s.addItem('A', 1.5), /INVALID_QTY/);
});

